import imageWidths from '../content/image-widths.json'

// Widths available per base path, generated by scripts/responsive.mjs. The
// last entry is the original's own width (served from `${src}.webp`).
const widths: Record<string, number[]> = imageWidths

function variantUrl(src: string, width: number, available: number[]) {
  return width === available[available.length - 1]
    ? `${src}.webp`
    : `/images/sizes${src.slice('/images'.length)}-${width}.webp`
}

export function srcSetFor(src: string) {
  const available = widths[src]
  return available?.map((w) => `${variantUrl(src, w, available)} ${w}w`).join(', ')
}

// Smallest variant at least `minWidth` wide, e.g. for video posters.
export function imageAt(src: string, minWidth: number) {
  const available = widths[src]
  if (!available) return `${src}.webp`
  return variantUrl(src, available.find((w) => w >= minWidth) ?? available[available.length - 1], available)
}
